mapper.select:
SELECT MAX(R.CX_BATCH_NO) CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ MAX(R.BIG_ROLL_CODE) BIG_ROLL_CODE, /*帘线规格*/ R.CLOTH_CODE, /*胎体布代号*/ MAX(R.CRAFT) CRAFT, /*胎体布工艺*/ R.LAYERS, /*层数，开关打开会分层*/ MAX(R.TIRE_FABRIC_SIDE_RUBBER) EDGE_GLUE, /*半钢边胶*/ SUM((IFNULL(R.CLASS3_PLAN_QTY, 0)) * IFNULL(R.SIDEWALL_LENGTH, 0) / 1000) DAY_PLAN_QTY, /*夜班计划量*/ SUM((IFNULL(R.CLASS4_PLAN_QTY, 0)) * IFNULL(R.SIDEWALL_LENGTH, 0) / 1000) NIGHT_PLAN_QTY, /*早班计划量*/
IFNULL(ROUND(AVG(R.SIDEWALL_LENGTH), 3), 0) UNIT_CONSUME, /*单耗*/ IFNULL(CEILING(SUM(R.CLASS1_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS1_PLAN, /*对应成型一班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS2_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS2_PLAN, /*对应成型二班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS3_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS3_PLAN, /*对应成型三班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS4_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS4_PLAN, /*对应成型次一班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS5_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS5_PLAN, /*对应成型次二班的计划量，向上取整*/ COUNT(1) SPEC_COUNT FROM (SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE1 CLOTH_CODE, /*1#胎体布代号*/ TRUNCATE(CI.TIRE_FABRIC_CRAFT1, 0) CRAFT, /*1#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ IFNULL(CI.TIRE_FABRIC_LENGTH1, 0) SIDEWALL_LENGTH, /*单耗*/ IFNULL(R.CLASS3_PLANNED_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, 1 layers FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 != ''
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
UNION ALL SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE2 CLOTH_CODE, /*2#胎体布代号*/ TRUNCATE(CI.TIRE_FABRIC_CRAFT2, 0) CRAFT, /*2#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ IFNULL(CI.TIRE_FABRIC_LENGTH2, 0) SIDEWALL_LENGTH, /*单耗*/ IFNULL(R.CLASS3_PLANNED_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, CASE WHEN p.PARAM_VALUE = '1' THEN 2 ELSE 1 END layers FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION LEFT JOIN T_CD90_PARAMS p ON p.DEL_FLAG = '0' AND p.PARAM_CODE = 'SPLIT_LAYERS_SWITCH' WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 != ''
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
UNION ALL SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE3 CLOTH_CODE, /*3#胎体布代号*/ TRUNCATE(CI.TIRE_FABRIC_CRAFT3, 0) CRAFT, /*3#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ IFNULL(CI.TIRE_FABRIC_LENGTH3, 0) SIDEWALL_LENGTH, /*单耗*/ IFNULL(R.CLASS3_PLANNED_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, CASE WHEN p.PARAM_VALUE = '1' THEN 3 ELSE 1 END layers FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION LEFT JOIN T_CD90_PARAMS p ON p.DEL_FLAG = '0' AND p.PARAM_CODE = 'SPLIT_LAYERS_SWITCH' WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 != ''
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
) R GROUP BY R.SCHEDULE_DATE, R.CLOTH_CODE, R.LAYERS
HAVING SUM((IFNULL(R.CLASS1_PLAN_QTY, 0) + IFNULL(R.CLASS2_PLAN_QTY, 0) + IFNULL(R.CLASS3_PLAN_QTY, 0) + IFNULL(R.CLASS4_PLAN_QTY, 0) + IFNULL(R.CLASS5_PLAN_QTY, 0)) * R.SIDEWALL_LENGTH) != 0 ORDER BY BIG_ROLL_CODE, CLOTH_CODE, LAYERS

WITH temp_tab_cloth_code AS (
SELECT #{schedule.clothCode} cloth_code FROM dual
) SELECT CASE WHEN MAX(CX_BATCH_NO) IS NULL THEN IFNULL(ROUND(MAX(UNIT_CONSUME), 3), 0) ELSE MAX(CASE WHEN CX_BATCH_NO IS NOT NULL THEN UNIT_CONSUME ELSE NULL END) END UNIT_CONSUME, /*当能关联上成型时需要按成型对应的版本取值，否则取最大值*/ MAX(BIG_ROLL_CODE) BIG_ROLL_CODE, MAX(CRAFT) CRAFT, /*工艺*/ MAX(TIRE_FABRIC_SIDE_RUBBER) EDGE_GLUE, /*半钢边胶*/ CLOTH_CODE, MAX(CX_BATCH_NO) CX_BATCH_NO, LAYERS, IFNULL(CEILING(SUM(R.CLASS1_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS1_PLAN, /*对应成型一班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS2_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS2_PLAN, /*对应成型二班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS3_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS3_PLAN, /*对应成型三班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS4_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS4_PLAN, /*对应成型次一班的计划量，向上取整*/ IFNULL(CEILING(SUM(R.CLASS5_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS5_PLAN /*对应成型次二班的计划量，向上取整*/ FROM ( SELECT CI.TIRE_FABRIC_LENGTH1 UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE1 CLOTH_CODE, TRUNCATE(CI.TIRE_FABRIC_CRAFT1, 0) CRAFT, /*1#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ IFNULL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.TIRE_FABRIC_LENGTH1 SIDEWALL_LENGTH, 1 layers FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) UNION SELECT CI.TIRE_FABRIC_LENGTH2 UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE2 CLOTH_CODE, TRUNCATE(CI.TIRE_FABRIC_CRAFT2, 0) CRAFT, /*2#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ IFNULL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.TIRE_FABRIC_LENGTH2 SIDEWALL_LENGTH, CASE WHEN p.PARAM_VALUE = '1' THEN 2 ELSE 1 END layers FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} LEFT JOIN T_CD90_PARAMS p ON p.DEL_FLAG = '0' AND p.PARAM_CODE = 'SPLIT_LAYERS_SWITCH' WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) UNION SELECT CI.TIRE_FABRIC_LENGTH3 UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE3 CLOTH_CODE, TRUNCATE(CI.TIRE_FABRIC_CRAFT3, 0) CRAFT, /*3#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ IFNULL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, IFNULL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, IFNULL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, IFNULL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, IFNULL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.TIRE_FABRIC_LENGTH3 SIDEWALL_LENGTH, CASE WHEN p.PARAM_VALUE = '1' THEN 3 ELSE 1 END layers FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} LEFT JOIN T_CD90_PARAMS p ON p.DEL_FLAG = '0' AND p.PARAM_CODE = 'SPLIT_LAYERS_SWITCH' WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) ) R GROUP BY CLOTH_CODE, LAYERS

mapper.update:
		UPDATE T_CD90_AUTO_SCHEDULE_RECORD
		SET DEL_FLAG  = '1',
			UPDATE_BY = #{createBy},
    	       UPDATE_TIME = #{createTime}
    	 WHERE schedule_date = #{scheduleDate}
    	   AND DEL_FLAG = '0'

UPDATE T_CD90_SCHEDULE_RESULT as a JOIN (
SELECT #{item.id} AS id, #{item.batchNo} as batch_no, #{item.orderNo} as order_no FROM DUAL
) tempTable ON a.id = tempTable.id SET a.batch_no = tempTable.batch_no, a.order_no = tempTable.order_no where a.del_flag = '0'
